#!/usr/bin/env bash
# Docker smoke test: build the image, run it with only the brief's env vars, exercise the
# endpoints against the challenge test server (run locally), then re-create the container
# on the same volume and check the data is still there.
#   HARNESS=/path/to/harness/server.js test/docker-smoke.sh
# Uses throwaway credentials generated by the local test server; nothing real.
set -euo pipefail

HARNESS=${HARNESS:?set HARNESS to the challenge harness/server.js}
H_PORT=4500
APP_PORT=8088
IMAGE=back-in-stock:smoke
VOL=restock-smoke-data
H=http://127.0.0.1:$H_PORT
A=http://127.0.0.1:$APP_PORT
WORK=$(mktemp -d)
HPID=""

cleanup() {
  docker rm -f bis-smoke >/dev/null 2>&1 || true
  docker volume rm -f "$VOL" >/dev/null 2>&1 || true
  [ -n "$HPID" ] && kill "$HPID" 2>/dev/null || true
  rm -rf "$WORK"
}
trap cleanup EXIT

step() { echo; echo "== $*"; }
fail() { echo "FAIL: $*"; docker logs bis-smoke 2>&1 | tail -40 || true; exit 1; }
wait_up() { for _ in $(seq 1 60); do curl -fs "$1/healthz" >/dev/null 2>&1 && return 0; sleep 0.5; done; fail "$1 did not come up"; }
jget() { node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{const v=JSON.parse(s);console.log(eval('v'+process.argv[1]))})" "$1"; }
code() { curl -s -o /dev/null -w '%{http_code}' "$@"; }

step "Start the challenge test server locally"
PORT=$H_PORT DATA_DIR="$WORK/h" SIM_INTERVAL_SECONDS=100000 INVITE_CODE= node "$HARNESS" >"$WORK/h.log" 2>&1 &
HPID=$!
wait_up "$H"
LOC=$(curl -s -o /dev/null -w '%{redirect_url}' -X POST -d 'name=docker-smoke' "$H/signup")
TOKEN=${LOC##*/c/}
sleep 0.5
read -r KEY SECRET < <(node -e "const c=Object.values(require(process.argv[1]).candidates)[0];console.log(c.apiKey,c.webhookSecret)" "$WORK/h/db.json")
echo "::add-mask::$KEY"; echo "::add-mask::$SECRET"
# Docker on Linux with --network host reaches the harness on 127.0.0.1.
curl -s -o /dev/null -X POST -d "baseUrl=$A" "$H/c/$TOKEN/baseurl"
curl -s -o /dev/null -X POST -d 'action=stop' "$H/c/$TOKEN/sim"
curl -s -o /dev/null -X POST -d 'sku=SMOKE-1&quantity=0' "$H/c/$TOKEN/stock"

step "docker build"
docker build -t "$IMAGE" .

run_app() {
  docker run -d --name bis-smoke --network host -v "$VOL:/data" \
    -e PORT=$APP_PORT \
    -e STOCK_API_URL="$H/api/stock" -e STOCK_API_KEY="$KEY" \
    -e RESEND_API_KEY="$KEY" -e RESEND_BASE_URL="$H" \
    -e WEBHOOK_SECRET="$SECRET" -e ADMIN_PASSWORD=smoke-admin-pw \
    "$IMAGE" >/dev/null
  wait_up "$A"
}

step "docker run (env vars from the brief only, listening on \$PORT=$APP_PORT)"
run_app
docker logs bis-smoke 2>&1 | head -5

step "Endpoints"
[ "$(code "$A/embed")" = 200 ] || fail "/embed"
[ "$(code "$A/admin/requests.json")" = 401 ] || fail "/admin should need a password"
[ "$(code -u admin:smoke-admin-pw "$A/admin")" = 200 ] || fail "/admin with password"
[ "$(code -X POST -H 'content-type: application/json' -H 'x-webhook-secret: wrong' -d '{"event_id":"e1","sku":"SMOKE-1","quantity":3}' "$A/webhooks/stock")" = 401 ] || fail "bad webhook secret accepted"
R=$(curl -s -X POST -H 'content-type: application/json' -d '{"email":"smoke@example.com","sku":"SMOKE-1"}' "$A/api/requests")
[ "$(echo "$R" | jget .result)" = waiting ] || fail "request not created: $R"
R=$(curl -s -X POST -H 'content-type: application/json' -d '{"email":"smoke@example.com","sku":"SMOKE-1"}' "$A/api/requests")
[ "$(echo "$R" | jget .result)" = already_waiting ] || fail "duplicate request: $R"
echo "embed 200, admin protected, bad secret 401, request created, duplicate rejected"

step "Restart: docker restart keeps data"
docker restart bis-smoke >/dev/null; wait_up "$A"
N=$(curl -s -u admin:smoke-admin-pw "$A/admin/requests.json" | jget .stats.waiting)
[ "$N" = 1 ] || fail "after docker restart expected 1 waiting request, got $N"
echo "1 waiting request after docker restart"

step "Re-create the container on the same volume"
docker rm -f bis-smoke >/dev/null
run_app
N=$(curl -s -u admin:smoke-admin-pw "$A/admin/requests.json" | jget .stats.waiting)
[ "$N" = 1 ] || fail "after re-create expected 1 waiting request, got $N"
echo "1 waiting request after container re-create"

step "Restock delivered twice -> exactly one email"
curl -s -X POST -H "authorization: Bearer $KEY" -H 'content-type: application/json' \
  -d '{"sku":"SMOKE-1","quantity":5,"twice":true}' "$H/api/test/restock" | jget .deliveries
for _ in $(seq 1 40); do
  [ "$(curl -s -u admin:smoke-admin-pw "$A/admin/requests.json" | jget .stats.notified)" = 1 ] && break; sleep 0.5
done
sleep 1.5
SENT=$(node -e "const c=Object.values(require(process.argv[1]).candidates)[0];console.log(c.emails.filter(e=>e.to.includes('smoke@example.com')&&e.status==='accepted').length)" "$WORK/h/db.json")
[ "$SENT" = 1 ] || fail "expected exactly 1 email, harness inbox has $SENT"
echo "harness inbox: 1 email to smoke@example.com"

echo; echo "DOCKER SMOKE TEST PASSED"
